const entrada = $json.body?.chatInput ?? $json.chatInput ?? '';
const texto = String(entrada).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

const temasFinanceAI = [
  'financeai', 'finanza', 'finanzas', 'financiero', 'financiera', 'gasto', 'gastos',
  'ingreso', 'ingresos', 'deuda', 'endeudamiento', 'ahorro', 'ahorrar', 'presupuesto',
  'transaccion', 'transacciones', 'categoria', 'categorias', 'alimentacion', 'transporte',
  'salud', 'vivienda', 'educacion', 'ocio', 'servicio', 'perfil', 'saludable',
  'observacion', 'riesgo', 'recomendacion', 'diagnostico', 'modelo', 'csv', 'analisis',
  'moneda', 'dolar', 'peso', 'sol', 'real', 'api', 'soporte', 'aplicacion', 'plataforma',
  'reporte', 'informe', 'historial', 'clasificar', 'clasificacion', 'confianza', 'hola',
  'buenos dias', 'buenas tardes', 'buenas noches', 'ayuda'
];

const tieneTema = temasFinanceAI.some((tema) => texto.includes(tema));

// Los mensajes cortos suelen ser continuaciones: "si", "y que mas", "explicame
// eso". Exigirles una palabra financiera rompe la conversacion, porque el
// agente pregunta algo y el filtro rechaza la respuesta. Se dejan pasar y es el
// system prompt del agente quien mantiene el tema.
const palabras = texto ? texto.split(/\s+/).length : 0;
const esContinuacion = palabras > 0 && palabras <= 5;

return [{
  json: {
    ...$json,
    financeAiPermitido: tieneTema || esContinuacion,
    respuestaFueraAlcance: 'Soy el asistente virtual oficial de FinanceAI. Únicamente puedo responder dudas sobre nuestra plataforma de finanzas y dar soporte técnico de la aplicación.'
  }
}];
